import json
B = [0] * 5
def write(j, y):
    for k in range(5):
        B[k] = (B[k] & ~(1 << j)) | (((y >> k) & 1) << j)
def gather(j):
    return sum((2 ** k) * ((B[k] >> j) & 1) for k in range(5))
for j, y in [(0, 19), (3, 6), (63, 31), (3, 9)]:
    write(j, y)
print(json.dumps({"planes": B, "reads": [gather(0), gather(3), gather(63)]}))
